-- Pedidos compartidos: el navegador solo envía nombres; la clave se resuelve y guarda en el servidor.
create or replace function public.glp_create_generated_order_from_catalog(
 p_title text,p_instructions text,p_difficulty text,p_determinations text[],p_expires_at timestamptz default null
) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_token text; v_id uuid; v_order jsonb; v_key jsonb; v_count integer;
begin
 if v_uid is null or not public.is_glp_admin() then raise exception 'Solo un docente administrador puede generar pedidos'; end if;
 if p_difficulty not in ('Inicial','Intermedio','Avanzado') then raise exception 'Dificultad inválida'; end if;
 v_count:=coalesce(array_length(p_determinations,1),0);
 if v_count<1 or v_count>40 then raise exception 'Cantidad de determinaciones inválida'; end if;
 if (select count(distinct name) from unnest(p_determinations) as u(name))<>v_count then raise exception 'No se permiten determinaciones repetidas'; end if;
 if p_expires_at is not null and p_expires_at<=now() then raise exception 'La fecha de vencimiento debe ser futura'; end if;
 select jsonb_agg(jsonb_build_object('numero',q.ord,'determinacion',q.data->>'Determinación') order by q.ord),
        jsonb_agg(jsonb_build_object(
          'determinacion',q.data->>'Determinación','area',coalesce(q.data->>'Sector',q.data->>'Grupo',''),
          'muestra',coalesce(q.data->>'Muestra',''),'tubo',coalesce(q.data->>'Tubo',''),
          'aditivo',coalesce(q.data->>'Aditivo',''),'ayuno',coalesce(q.data->>'Ayuno',''),
          'toma',coalesce(q.data->>'Toma',''),'procesamiento',coalesce(q.data->>'Procesamiento',''),
          'condiciones',coalesce(q.data->>'Condiciones especiales',''),'observaciones',coalesce(q.data->>'Observaciones','')
        ) order by q.ord)
 into v_order,v_key
 from unnest(p_determinations) with ordinality as n(name,ord)
 join public.glp_determination_catalog c on c.determination=n.name and c.enabled
 cross join lateral (select c.data,n.ord) q(data,ord);
 if jsonb_array_length(coalesce(v_order,'[]'::jsonb))<>v_count then raise exception 'Una o más determinaciones ya no están disponibles en el catálogo'; end if;
 v_token:=replace(gen_random_uuid()::text,'-','');
 insert into public.glp_generated_orders(owner_id,token,title,instructions,difficulty,item_count,order_data,answer_key,expires_at)
 values(v_uid,v_token,coalesce(nullif(trim(p_title),''),'Pedido simulado'),coalesce(p_instructions,''),p_difficulty,v_count,v_order,v_key,p_expires_at)
 returning id into v_id;
 return jsonb_build_object('id',v_id,'token',v_token,'item_count',v_count);
end; $$;
revoke all on function public.glp_create_generated_order_from_catalog(text,text,text,text[],timestamptz) from public,anon;
grant execute on function public.glp_create_generated_order_from_catalog(text,text,text,text[],timestamptz) to authenticated;

-- Asegura que los nuevos pedidos individuales se generen en el servidor y nunca reciban la clave en el navegador.
drop function if exists public.glp_create_random_assignment(text,text,text,jsonb,jsonb);
create or replace function public.glp_create_random_assignment(
 p_session_token text,p_student_name text,p_client_key text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_s public.glp_random_sessions; v_token text; v_id uuid; v_name text; v_order jsonb; v_key jsonb; v_try integer:=0;
begin
 select * into v_s from public.glp_random_sessions where token=p_session_token;
 if not found then raise exception 'La actividad no existe'; end if;
 if v_s.expires_at is not null and v_s.expires_at<now() then raise exception 'El enlace de esta actividad venció'; end if;
 if p_client_key is null or length(p_client_key)<12 or length(p_client_key)>100 then raise exception 'Identificador de sesión inválido'; end if;
 v_name:=left(trim(coalesce(p_student_name,'')),100);
 if v_name='' then raise exception 'Ingresá tu nombre y apellido'; end if;
 -- Recuperar primero por navegador y luego por nombre para permitir reingreso desde otro dispositivo.
 select token,id into v_token,v_id from public.glp_generated_orders where session_id=v_s.id and client_key=p_client_key;
 if found then return jsonb_build_object('token',v_token,'id',v_id,'recovered',true); end if;
 select token,id into v_token,v_id from public.glp_generated_orders where session_id=v_s.id and lower(regexp_replace(trim(assigned_student_name),'\s+',' ','g'))=lower(regexp_replace(v_name,'\s+',' ','g')) order by created_at limit 1;
 if found then return jsonb_build_object('token',v_token,'id',v_id,'recovered',true); end if;
 if v_s.status<>'active' then raise exception 'La actividad fue cerrada y no admite nuevos alumnos'; end if;
 loop
   select jsonb_agg(jsonb_build_object('numero',x.ord,'determinacion',x.data->>'Determinación') order by x.ord),
          jsonb_agg(jsonb_build_object(
            'determinacion',x.data->>'Determinación','area',coalesce(x.data->>'Sector',x.data->>'Grupo',''),
            'muestra',coalesce(x.data->>'Muestra',''),'tubo',coalesce(x.data->>'Tubo',''),
            'aditivo',coalesce(x.data->>'Aditivo',''),'ayuno',coalesce(x.data->>'Ayuno',''),
            'toma',coalesce(x.data->>'Toma',''),'procesamiento',coalesce(x.data->>'Procesamiento',''),
            'condiciones',coalesce(x.data->>'Condiciones especiales',''),'observaciones',coalesce(x.data->>'Observaciones','')
          ) order by x.ord)
   into v_order,v_key
   from (select c.data,row_number() over() as ord from public.glp_determination_catalog c where c.enabled order by random() limit v_s.item_count) x;
   if jsonb_array_length(coalesce(v_order,'[]'::jsonb))<>v_s.item_count then raise exception 'El catálogo no tiene suficientes determinaciones habilitadas'; end if;
   v_token:=replace(gen_random_uuid()::text,'-','');
   begin
     insert into public.glp_generated_orders(owner_id,token,title,instructions,difficulty,item_count,order_data,answer_key,expires_at,session_id,assigned_student_name,client_key)
     values(v_s.owner_id,v_token,v_s.title,v_s.instructions,v_s.difficulty,v_s.item_count,v_order,v_key,v_s.expires_at,v_s.id,v_name,p_client_key)
     returning id into v_id;
     return jsonb_build_object('token',v_token,'id',v_id,'recovered',false);
   exception when unique_violation then
     v_try:=v_try+1;
     if v_try>12 then raise exception 'No se pudo asignar una combinación única. Intentá nuevamente.'; end if;
   end;
 end loop;
end; $$;
revoke all on function public.glp_create_random_assignment(text,text,text) from public,anon;
grant execute on function public.glp_create_random_assignment(text,text,text) to anon,authenticated;

-- La asignación individual conserva el nombre original y lo expone como no editable.
create or replace function public.glp_get_generated_order(p_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_o public.glp_generated_orders;
begin
 select * into v_o from public.glp_generated_orders where token=p_token and status='active';
 if not found then raise exception 'Pedido inexistente o cerrado'; end if;
 if v_o.expires_at is not null and v_o.expires_at<now() then raise exception 'El enlace de este pedido venció'; end if;
 return jsonb_build_object('title',v_o.title,'instructions',v_o.instructions,'difficulty',v_o.difficulty,'item_count',v_o.item_count,'order_data',v_o.order_data,'expires_at',v_o.expires_at,'assigned_student_name',v_o.assigned_student_name,'is_individual',v_o.session_id is not null);
end; $$;

-- Guard anti doble entrega: columna derivada y unicidad solo para pedidos individuales.
alter table public.glp_generated_submissions add column if not exists individual_assignment boolean not null default false;
update public.glp_generated_submissions s set individual_assignment=true from public.glp_generated_orders o where o.id=s.order_id and o.session_id is not null;
create index if not exists glp_generated_submissions_individual_attempt_idx on public.glp_generated_submissions(order_id) where individual_assignment;
create or replace function public.glp_mark_individual_submission()
returns trigger language plpgsql security definer set search_path=public as $$
begin
 select (o.session_id is not null) into new.individual_assignment from public.glp_generated_orders o where o.id=new.order_id;
 return new;
end; $$;
drop trigger if exists glp_generated_submission_mark_individual on public.glp_generated_submissions;
create trigger glp_generated_submission_mark_individual before insert or update of order_id on public.glp_generated_submissions for each row execute function public.glp_mark_individual_submission();

-- Reemplaza el envío para bloquear duplicados incluso ante dos envíos simultáneos.
create or replace function public.glp_submit_generated_order(p_token text,p_student_name text,p_response jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_o public.glp_generated_orders; v_count integer; v_id uuid; v_access_code text;
begin
 select * into v_o from public.glp_generated_orders where token=p_token and status='active' for update;
 if not found then raise exception 'Pedido inexistente o cerrado'; end if;
 if v_o.expires_at is not null and v_o.expires_at<now() then raise exception 'El enlace de este pedido venció'; end if;
 if jsonb_typeof(p_response)<>'array' then raise exception 'La respuesta enviada no tiene un formato válido'; end if;
 v_count:=jsonb_array_length(p_response);
 if v_count<>v_o.item_count then raise exception 'La cantidad de respuestas no coincide con el pedido'; end if;
 if v_o.session_id is not null and lower(trim(coalesce(p_student_name,'')))<>lower(trim(coalesce(v_o.assigned_student_name,''))) then
   raise exception 'El nombre no coincide con el alumno asignado a este pedido';
 end if;
 if v_o.session_id is not null and exists(select 1 from public.glp_generated_submissions s where s.order_id=v_o.id) then raise exception 'Este pedido individual ya fue entregado. Utilizá tu código para consultar la devolución.'; end if;
 loop
  v_access_code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
  exit when not exists(select 1 from public.glp_generated_submissions s where s.access_code=v_access_code);
 end loop;
 insert into public.glp_generated_submissions(order_id,student_name,response,score,feedback,access_code,review_status)
 values(v_o.id,coalesce(nullif(trim(p_student_name),''),nullif(v_o.assigned_student_name,''),'Alumno'),p_response,0,jsonb_build_object('status','pending_teacher_review'),v_access_code,'pending')
 returning id into v_id;
 return jsonb_build_object('submission_id',v_id,'access_code',v_access_code,'review_status','pending','message','Entrega registrada. Guardá el código para consultar la devolución.');
end; $$;
revoke all on function public.glp_submit_generated_order(text,text,jsonb) from public;
grant execute on function public.glp_submit_generated_order(text,text,jsonb) to anon,authenticated;

-- Historial auditable de cambios de notas virtuales y presenciales.
create table if not exists public.glp_generated_grade_history (
 id uuid primary key default gen_random_uuid(),
 submission_id uuid not null references public.glp_generated_submissions(id) on delete cascade,
 changed_by uuid references auth.users(id) on delete set null,
 changed_at timestamptz not null default now(),
 field_name text not null check(field_name in ('pedido','presencial')),
 old_value jsonb,
 new_value jsonb
);
alter table public.glp_generated_grade_history enable row level security;
revoke all on public.glp_generated_grade_history from anon,authenticated;

-- Reemplaza la función de corrección para registrar cada modificación.
create or replace function public.glp_admin_grade_generated_submission(p_submission_id uuid,p_item_grades jsonb,p_teacher_feedback text default '')
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_s public.glp_generated_submissions; v_o public.glp_generated_orders; v_count integer; v_grade numeric(5,2);
begin
 if not public.is_glp_admin() then raise exception 'No autorizado'; end if;
 if jsonb_typeof(p_item_grades)<>'array' then raise exception 'Los puntajes deben enviarse como una lista'; end if;
 select * into v_s from public.glp_generated_submissions where id=p_submission_id for update;
 if not found then raise exception 'No se encontró la entrega'; end if;
 select * into v_o from public.glp_generated_orders where id=v_s.order_id and owner_id=auth.uid();
 if not found then raise exception 'No tenés permiso para corregir esta entrega'; end if;
 v_count:=jsonb_array_length(v_s.response);
 if jsonb_array_length(p_item_grades)<>v_count then raise exception 'Debe haber un puntaje por cada determinación'; end if;
 if exists(select 1 from jsonb_array_elements(p_item_grades) e(value) where jsonb_typeof(e.value)<>'number' or (e.value::text)::numeric<0 or (e.value::text)::numeric>100) then raise exception 'Cada puntaje debe estar entre 0 y 100'; end if;
 select round(avg((e.value::text)::numeric),2) into v_grade from jsonb_array_elements(p_item_grades) e(value);
 if v_s.item_grades is distinct from p_item_grades or v_s.teacher_grade is distinct from v_grade or v_s.teacher_feedback is distinct from coalesce(p_teacher_feedback,'') then
   insert into public.glp_generated_grade_history(submission_id,changed_by,field_name,old_value,new_value)
   values(p_submission_id,auth.uid(),'pedido',jsonb_build_object('item_grades',v_s.item_grades,'teacher_grade',v_s.teacher_grade,'teacher_feedback',v_s.teacher_feedback),jsonb_build_object('item_grades',p_item_grades,'teacher_grade',v_grade,'teacher_feedback',coalesce(p_teacher_feedback,'')));
 end if;
 update public.glp_generated_submissions set item_grades=p_item_grades,teacher_grade=v_grade,teacher_feedback=coalesce(p_teacher_feedback,''),review_status='graded',reviewed_at=now(),reviewed_by=auth.uid() where id=p_submission_id;
 return jsonb_build_object('teacher_grade',v_grade,'review_status','graded');
end; $$;

-- Reemplaza la nota presencial para registrar cambios.
create or replace function public.glp_admin_set_practical_grade(p_submission_id uuid,p_practical_grade numeric default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_old numeric; v_order public.glp_generated_orders;
begin
 if auth.uid() is null or not public.is_glp_admin() then raise exception 'No autorizado'; end if;
 if p_practical_grade is not null and (p_practical_grade<0 or p_practical_grade>100) then raise exception 'La calificación presencial debe estar entre 0 y 100'; end if;
 select o.* into v_order from public.glp_generated_submissions s join public.glp_generated_orders o on o.id=s.order_id where s.id=p_submission_id and o.owner_id=auth.uid();
 if not found then raise exception 'No se encontró la entrega o no tenés permiso'; end if;
 select practical_grade into v_old from public.glp_generated_submissions where id=p_submission_id for update;
 if v_old is distinct from p_practical_grade then
   insert into public.glp_generated_grade_history(submission_id,changed_by,field_name,old_value,new_value) values(p_submission_id,auth.uid(),'presencial',to_jsonb(v_old),to_jsonb(p_practical_grade));
 end if;
 update public.glp_generated_submissions set practical_grade=p_practical_grade,practical_grade_updated_at=case when p_practical_grade is null then null else now() end,practical_grade_updated_by=case when p_practical_grade is null then null else auth.uid() end where id=p_submission_id;
 return jsonb_build_object('practical_grade',p_practical_grade);
end; $$;

create or replace function public.glp_admin_get_grade_history(p_submission_id uuid)
returns table(changed_at timestamptz,field_name text,old_value jsonb,new_value jsonb,changed_by uuid)
language plpgsql security definer set search_path=public as $$
begin
 if not public.is_glp_admin() then raise exception 'No autorizado'; end if;
 if not exists(select 1 from public.glp_generated_submissions s join public.glp_generated_orders o on o.id=s.order_id where s.id=p_submission_id and o.owner_id=auth.uid()) then raise exception 'No autorizado'; end if;
 return query select h.changed_at,h.field_name,h.old_value,h.new_value,h.changed_by from public.glp_generated_grade_history h where h.submission_id=p_submission_id order by h.changed_at desc;
end; $$;
revoke all on function public.glp_admin_get_grade_history(uuid) from public,anon;
grant execute on function public.glp_admin_get_grade_history(uuid) to authenticated;

-- Asegura que la consulta pública de devolución nunca revele la clave antes de publicar.
create or replace function public.glp_get_generated_feedback(p_access_code text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_s public.glp_generated_submissions; v_o public.glp_generated_orders;
begin
 if p_access_code is null or length(trim(p_access_code))<>10 then return jsonb_build_object('found',false); end if;
 select * into v_s from public.glp_generated_submissions where access_code=upper(trim(p_access_code));
 if not found then return jsonb_build_object('found',false); end if;
 if v_s.review_status<>'graded' then return jsonb_build_object('found',true,'review_status','pending','student_name',v_s.student_name,'submitted_at',v_s.submitted_at); end if;
 select * into v_o from public.glp_generated_orders where id=v_s.order_id;
 return jsonb_build_object('found',true,'review_status','graded','student_name',v_s.student_name,'submitted_at',v_s.submitted_at,'response',v_s.response,'answer_key',v_o.answer_key,'item_grades',v_s.item_grades,'teacher_grade',v_s.teacher_grade,'teacher_feedback',v_s.teacher_feedback);
end; $$;
revoke all on function public.glp_get_generated_feedback(text) from public;
grant execute on function public.glp_get_generated_feedback(text) to anon,authenticated;


-- La exportación general también conserva la respuesta sobre el orden Vacutainer.
drop function if exists public.glp_admin_export_all_generated_grades();
create function public.glp_admin_export_all_generated_grades()
returns table(
  activity_title text,order_type text,student_name text,submitted_at timestamptz,
  review_status text,order_grade numeric,practical_grade numeric,access_code text,
  teacher_feedback text,vacutainer_order text
)
language plpgsql security definer set search_path=public as $$
begin
 if auth.uid() is null or not public.is_glp_admin() then raise exception 'No autorizado'; end if;
 return query
 select o.title,
   case when o.session_id is null then 'Pedido compartido' else 'Pedido aleatorio individual' end,
   s.student_name,s.submitted_at,s.review_status,s.teacher_grade,s.practical_grade,
   s.access_code,s.teacher_feedback,s.response->0->>'orden_llenado_vacutainer'
 from public.glp_generated_submissions s
 join public.glp_generated_orders o on o.id=s.order_id
 where o.owner_id=auth.uid()
 order by s.submitted_at desc;
end; $$;
revoke all on function public.glp_admin_export_all_generated_grades() from public,anon;
grant execute on function public.glp_admin_export_all_generated_grades() to authenticated;

notify pgrst, 'reload schema';
